import json, time, urllib.error, urllib.parse, urllib.request
from pathlib import Path

def load_key():
    for line in Path(".env").read_text(errors="replace").splitlines():
        s = line.strip()
        if not s or s.startswith("#") or "=" not in s:
            continue
        k, v = s.split("=", 1)
        if k.strip() == "SERPAPI_API_KEY":
            return v.strip().strip('"').strip("'")
    raise SystemExit("missing key")

KEY = load_key()

def redact(text):
    if not isinstance(text, str):
        text = str(text)
    return text.replace(KEY, "[redacted]")

def call(url, params, timeout=20):
    q = dict(params)
    q["api_key"] = KEY
    full = url + "?" + urllib.parse.urlencode(q)
    req = urllib.request.Request(full, headers={"Accept": "application/json"})
    started = time.perf_counter()
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read()
            elapsed = round(time.perf_counter() - started, 3)
            return resp.status, elapsed, json.loads(raw.decode())
    except urllib.error.HTTPError as e:
        elapsed = round(time.perf_counter() - started, 3)
        body = redact(e.read().decode(errors="replace")[:400])
        return e.code, elapsed, {"http_error": body}
    except Exception as e:
        elapsed = round(time.perf_counter() - started, 3)
        return 0, elapsed, {"error": redact(type(e).__name__ + ": " + str(e)[:240])}

def scrub_account(data):
    if not isinstance(data, dict):
        return data
    keep = [
        "plan_name", "plan_id", "searches_per_month", "plan_searches_left",
        "extra_credits", "total_searches_left", "this_month_usage",
        "this_hour_searches", "account_rate_limit_per_hour",
    ]
    return {k: data.get(k) for k in keep if k in data}

def hours_info(place):
    op = place.get("operating_hours")
    hours = place.get("hours")
    days = 0
    sample_type = None
    if isinstance(op, dict) and op:
        days = len(op)
        sample_type = "operating_hours_dict"
    elif isinstance(hours, list) and hours:
        days = len(hours)
        sample_type = "hours_list"
    elif isinstance(hours, dict) and hours:
        days = len(hours)
        sample_type = "hours_dict"
    return {"present": days > 0, "days": days, "shape": sample_type}

def popular_info(place):
    pop = place.get("popular_times")
    if not isinstance(pop, dict):
        return {"present": False}
    graph = pop.get("graph_results")
    days = list(graph.keys()) if isinstance(graph, dict) else []
    points = 0
    if isinstance(graph, dict):
        for rows in graph.values():
            if isinstance(rows, list):
                points += len(rows)
    return {
        "present": bool(days),
        "days": days,
        "points": points,
        "has_live": "live_hash" in pop or "live" in pop,
    }

def place_summary(place):
    return {
        "title": place.get("title"),
        "type": place.get("type"),
        "types": place.get("types"),
        "place_id_present": bool(place.get("place_id")),
        "data_id_present": bool(place.get("data_id")),
        "place_id": place.get("place_id"),
        "data_id": place.get("data_id"),
        "rating_present": place.get("rating") is not None,
        "reviews_count": place.get("reviews"),
        "gps": bool(place.get("gps_coordinates")),
        "address_present": bool(place.get("address")),
        "hours": hours_info(place),
        "popular_times": popular_info(place),
    }

summary = {"calls": []}

status, elapsed, account = call("https://serpapi.com/account.json", {})
summary["account_http"] = status
summary["account_seconds"] = elapsed
summary["account"] = scrub_account(account) if status == 200 else account
if status != 200:
    print(json.dumps(summary, indent=2))
    raise SystemExit(0)

search_params = {
    "engine": "google_maps",
    "type": "search",
    "q": "restaurants in Indiranagar, Bengaluru",
    "hl": "en",
    "gl": "in",
}
status, elapsed, search = call("https://serpapi.com/search.json", search_params)
meta = search.get("search_metadata", {}) if isinstance(search, dict) else {}
local = search.get("local_results", []) if isinstance(search, dict) else []
if not isinstance(local, list):
    local = []
summary["calls"].append({
    "kind": "maps_search",
    "query": search_params["q"],
    "http": status,
    "seconds": elapsed,
    "provider_status": meta.get("status"),
    "search_id_present": bool(meta.get("id")),
    "local_count": len(local),
})
candidates = []
for item in local[:8]:
    if not isinstance(item, dict):
        continue
    candidates.append({
        "title": item.get("title"),
        "type": item.get("type"),
        "place_id": item.get("place_id"),
        "data_id": item.get("data_id"),
        "rating": item.get("rating"),
        "reviews": item.get("reviews"),
        "hours_in_search": hours_info(item)["present"],
    })
summary["search_candidates"] = candidates

# Detail the first three with ids. Stop early once two have hours and popular times.
detailed = []
rich = 0
for cand in candidates:
    if len(detailed) >= 3 or rich >= 2:
        break
    if not cand.get("place_id") and not cand.get("data_id"):
        continue
    params = {"engine": "google_maps", "type": "place", "hl": "en", "gl": "in"}
    if cand.get("place_id"):
        params["place_id"] = cand["place_id"]
    else:
        params["data_id"] = cand["data_id"]
    status, elapsed, place_body = call("https://serpapi.com/search.json", params)
    meta = place_body.get("search_metadata", {}) if isinstance(place_body, dict) else {}
    place = place_body.get("place_results", {}) if isinstance(place_body, dict) else {}
    if not isinstance(place, dict):
        place = {}
    info = place_summary(place)
    info["http"] = status
    info["seconds"] = elapsed
    info["provider_status"] = meta.get("status")
    info["top_level_keys"] = sorted(place.keys())
    detailed.append(info)
    if info["hours"]["present"] and info["popular_times"]["present"]:
        rich += 1
summary["place_details"] = detailed

review_target = None
for info in detailed:
    if info.get("data_id") or info.get("place_id"):
        review_target = info
        if info["popular_times"]["present"]:
            break
if review_target:
    params = {"engine": "google_maps_reviews", "hl": "en", "sort_by": "qualityScore"}
    if review_target.get("data_id"):
        params["data_id"] = review_target["data_id"]
    else:
        params["place_id"] = review_target["place_id"]
    status, elapsed, reviews_body = call("https://serpapi.com/search.json", params)
    meta = reviews_body.get("search_metadata", {}) if isinstance(reviews_body, dict) else {}
    reviews = reviews_body.get("reviews", []) if isinstance(reviews_body, dict) else []
    if not isinstance(reviews, list):
        reviews = []
    snippets = []
    dates = 0
    links = 0
    for rev in reviews:
        if not isinstance(rev, dict):
            continue
        text = rev.get("snippet") or rev.get("extracted_snippet") or ""
        if isinstance(text, dict):
            text = text.get("original") or ""
        if isinstance(text, str) and text.strip():
            snippets.append(len(text.strip()))
        if rev.get("date") or rev.get("iso_date"):
            dates += 1
        if rev.get("link") or rev.get("source"):
            links += 1
    summary["reviews"] = {
        "target": review_target.get("title"),
        "http": status,
        "seconds": elapsed,
        "provider_status": meta.get("status"),
        "returned": len(reviews),
        "with_snippet": len(snippets),
        "snippet_lengths": snippets[:8],
        "with_date": dates,
        "with_link": links,
        "top_level_keys": sorted(reviews_body.keys()) if isinstance(reviews_body, dict) else [],
    }

summary["search_calls"] = len(summary["calls"]) + len(summary.get("place_details", [])) + (1 if summary.get("reviews") else 0)
out = Path("/tmp/happen-serpapi-probe.json")
out.write_text(json.dumps(summary, indent=2))
print(json.dumps(summary, indent=2))
