import json, re, time
from pathlib import Path

def rss_mb():
    text = Path("/proc/self/status").read_text()
    vals = {}
    for key in ("VmRSS:", "VmHWM:"):
        for line in text.splitlines():
            if line.startswith(key):
                vals[key] = round(int(line.split()[1]) / 1024, 1)
    return vals

excerpt = "We sat in a quiet corner and talked for an hour without being rushed."
prompt = f"""Return one JSON object and no other text.
Schema:
{{
  "schema_version": "1",
  "excerpt_id": "e1",
  "signals": [
    {{
      "dimension": "conversation|short_wait|seating",
      "polarity": "positive|negative|mixed",
      "temporal_hint": "general",
      "temporal_span": null,
      "quoted_span": "exact substring of the excerpt",
      "confidence": "low|medium|high"
    }}
  ],
  "unknown_dimensions": ["conversation|short_wait|seating"]
}}
Rules: quoted_span must be copied exactly from the excerpt. Put every dimension you cannot support in unknown_dimensions. Do not invent a wait time or a seat type.
Excerpt e1: "{excerpt}"
"""

from llama_cpp import Llama
t0 = time.perf_counter()
llm = Llama(
    model_path="/tmp/happen-models/gemma-3-270m-it-Q4_K_M.gguf",
    n_ctx=1024,
    n_threads=2,
    n_batch=128,
    verbose=False,
)
load_s = round(time.perf_counter() - t0, 3)
after_load = rss_mb()

def generate():
    t1 = time.perf_counter()
    result = llm.create_chat_completion(
        messages=[{"role": "user", "content": prompt}],
        temperature=0,
        max_tokens=220,
    )
    elapsed = round(time.perf_counter() - t1, 3)
    text = result["choices"][0]["message"]["content"]
    return elapsed, text

def parse(text):
    raw = text.strip()
    fenced = re.search(r"```(?:json)?\s*(.*?)```", raw, re.S)
    candidate = fenced.group(1).strip() if fenced else raw
    start = candidate.find("{")
    end = candidate.rfind("}")
    if start == -1 or end == -1:
        return None, "no-object"
    try:
        obj = json.loads(candidate[start:end + 1])
    except json.JSONDecodeError as exc:
        return None, f"json-error:{exc.msg}"
    return obj, "parsed"

elapsed, text = generate()
obj, status = parse(text)
retry = None
if obj is None:
    elapsed2, text2 = generate()
    obj2, status2 = parse(text2)
    retry = {"seconds": elapsed2, "status": status2, "chars": len(text2)}
    if obj2 is not None:
        obj, status, text, elapsed = obj2, status2, text2, elapsed2

accepted = []
rejected = []
if isinstance(obj, dict):
    for signal in obj.get("signals") or []:
        if not isinstance(signal, dict):
            rejected.append("not-object")
            continue
        span = signal.get("quoted_span")
