    "retry": retry,
    "output_chars": len(text),
    "output_preview": text[:500],
    "accepted_signals": accepted,
    "rejected_signal_dimensions": rejected,
    "unknown_dimensions": obj.get("unknown_dimensions") if isinstance(obj, dict) else None,
}, indent=2))
